**Finding (Correctness — Blocking):** `parseInt(price)` stops parsing at the decimal point, truncating fractional currency values (e.g., `"19.99"` becomes `19`, `"0.75"` becomes `0`) and silently accepting trailing garbage like `"12.50abc"`.

**Scope & Checks:** Static inspection of the provided line; no test suite or compiler check ran.

**Correction:**
```ts
const trimmed = price.trim();
const amount = trimmed.length > 0 ? Number(trimmed) : Number.NaN;
if (!Number.isFinite(amount)) {
  throw new RangeError(`Invalid currency string: ${price}`);
}
```

**Regression Test:**
```ts
import { describe, expect, it } from "vitest";

function parsePrice(price: string): number {
  const trimmed = price.trim();
  const amount = trimmed.length > 0 ? Number(trimmed) : Number.NaN;
  if (!Number.isFinite(amount)) {
    throw new RangeError(`Invalid currency string: ${price}`);
  }
  return amount;
}

describe("parsePrice", () => {
  it("preserves decimal precision and rejects malformed strings", () => {
    expect(parsePrice("19.99")).toBe(19.99);
    expect(parsePrice("0.75")).toBe(0.75);
    expect(() => parsePrice("19.99USD")).toThrow(RangeError);
    expect(() => parsePrice("")).toThrow(RangeError);
  });
});
```
